    //#region LookUps Finalizers
     var finalizeAllLookUpTcsUsuarioAutenticacao = function (replaceTo, selectedElements, propertyName, lookupInfo) {
        if (!replaceTo || !selectedElements)
            return;
        if (!Array.isArray(selectedElements)) {
            selectedElements = [selectedElements];
        }
        var originalRow = replaceTo;
        var hasDisconsideredElement = false;
        var parent = getAbsoluteValue(replaceTo.TcsAmbiente);
        isFinalizingLookup(true);
        if (!propertyName)
            propertyName = '';
        var isUsedOriginalRow = false;
        for (var i = 0; i < selectedElements.length; i++)
        {
            var selectedElement = selectedElements[i];
            var isInvalidElement = false;
            var curList = parent.TcsAmbienteUsuarioAcessoList();
            for (var idx = 0; idx < curList.length; idx++) {
               if (curList[idx] != originalRow && getAbsoluteValue(curList[idx].IdUsuario) === getAbsoluteValue(selectedElement['IdUsuario'])) {
                   isInvalidElement = true;
                   hasDisconsideredElement = true;
                   break;
               }
            }
            if (isInvalidElement) continue;
            if (isUsedOriginalRow) {
                replaceTo = lookupInfo.vm.createTcsAmbienteUsuarioAcesso(parent);
            }
            else {
                isUsedOriginalRow = true;
            }
            if (propertyName === '' || propertyName === 'NomeUsuario') {
               if (selectedElement.hasOwnProperty('NomeUsuario') && replaceTo.hasOwnProperty('NomeUsuario'))
               {
                   setAbsoluteValue(replaceTo, 'NomeUsuario', getAbsoluteValue(selectedElement['NomeUsuario']));
               }
               else if (replaceTo.hasOwnProperty('NomeUsuario')) {
                   setAbsoluteValue(replaceTo, 'NomeUsuario', '');
               }
            }
            if (propertyName === '' || propertyName === 'NomeEmpresa') {
               if (selectedElement.hasOwnProperty('NomeEmpresa') && replaceTo.hasOwnProperty('NomeEmpresa'))
               {
                   setAbsoluteValue(replaceTo, 'NomeEmpresa', getAbsoluteValue(selectedElement['NomeEmpresa']));
               }
               else if (replaceTo.hasOwnProperty('NomeEmpresa')) {
                   setAbsoluteValue(replaceTo, 'NomeEmpresa', '');
               }
            }
            if (propertyName === '' || propertyName === 'IdLinx') {
               if (selectedElement.hasOwnProperty('IdLinx') && replaceTo.hasOwnProperty('IdLinx'))
               {
                   setAbsoluteValue(replaceTo, 'IdLinx', getAbsoluteValue(selectedElement['IdLinx']));
               }
               else if (replaceTo.hasOwnProperty('IdLinx')) {
                   setAbsoluteValue(replaceTo, 'IdLinx', 0);
               }
            }
            if (propertyName === '' || propertyName === 'IdUsuario') {
               if (selectedElement.hasOwnProperty('IdUsuario') && replaceTo.hasOwnProperty('IdUsuario'))
               {
                   setAbsoluteValue(replaceTo, 'IdUsuario', getAbsoluteValue(selectedElement['IdUsuario']));
               }
               else if (replaceTo.hasOwnProperty('IdUsuario')) {
                   setAbsoluteValue(replaceTo, 'IdUsuario', 0);
               }
            }
            if (propertyName === '' || propertyName === 'UidUsuario') {
               if (selectedElement.hasOwnProperty('UidUsuario') && replaceTo.hasOwnProperty('UidUsuario'))
               {
                   setAbsoluteValue(replaceTo, 'UidUsuario', getAbsoluteValue(selectedElement['UidUsuario']));
               }
               else if (replaceTo.hasOwnProperty('UidUsuario')) {
                   setAbsoluteValue(replaceTo, 'UidUsuario', '00000000-0000-0000-0000-000000000000');
               }
            }
            if (propertyName === '' || propertyName === 'NomeAutenticacao') {
               if (selectedElement.hasOwnProperty('NomeAutenticacao') && replaceTo.hasOwnProperty('NomeAutenticacao'))
               {
                   setAbsoluteValue(replaceTo, 'NomeAutenticacao', getAbsoluteValue(selectedElement['NomeAutenticacao']));
               }
               else if (replaceTo.hasOwnProperty('NomeAutenticacao')) {
                   setAbsoluteValue(replaceTo, 'NomeAutenticacao', '');
               }
            }
            if (replaceTo.validatedlookupsArray && !replaceTo.validatedlookupsArray.contains('LookUpTcsUsuarioAutenticacao'))
                replaceTo.validatedlookupsArray.push('LookUpTcsUsuarioAutenticacao');
        }
        //Trigger context data update event
        if (replaceTo.isPOCO) vm.refreshCurrentBind();
        document.dispatchEvent(dataUpdateEvent);
        isFinalizingLookup(false);
        if (hasDisconsideredElement) {
           clearLookUpTcsUsuarioAutenticacao(replaceTo);
           app.showMessage('Itens que já estão sendo utilizados foram desconsiderados nessa seleção!', 'Informação', ['Ok']);
        }
    };
    
    function clearLookUpTcsUsuarioAutenticacao(replaceTo) {
        if (!replaceTo)
            return;
        isClearingLookup(true);
        setAbsoluteValue(replaceTo, 'NomeUsuario', '');
        setAbsoluteValue(replaceTo, 'NomeEmpresa', '');
        setAbsoluteValue(replaceTo, 'IdLinx', 0);
        setAbsoluteValue(replaceTo, 'IdUsuario', 0);
        setAbsoluteValue(replaceTo, 'UidUsuario', '00000000-0000-0000-0000-000000000000');
        setAbsoluteValue(replaceTo, 'NomeAutenticacao', '');
        isClearingLookup(false);
        //Trigger context data update event
        if (replaceTo.isPOCO) vm.refreshCurrentBind();
        setTimeout(function () {document.dispatchEvent(dataUpdateEvent);}, 100);
    }
